using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NpcWorkTests
{
    static WorldSession New()=>new(NpcWork.Create());
    static void Accept(WorldSession s,bool yes=true){var c=RegionalWork.Inbox(s).Last();s.Open(ContractFixture.Officer,c.Message,s.Revision);s.Assent(s.DiagnosticSnapshot().Tasks.Last(t=>t.Action==ActionKind.Inspect).Id,ContractFixture.Officer,yes,s.Revision);s.SetPaused(false);}
    [Fact] public void LocalNpcDispatchesWithoutReadingRemoteOrPrivateIntent(){var s=New();Assert.Empty(s.DiagnosticSnapshot().Tasks);s.AdvanceTo(1);var w=s.DiagnosticSnapshot();Assert.Single(w.Tasks);Assert.Equal(new EntityId("person:nobunaga"),w.Tasks.Single().Issuer);Assert.Empty(RegionalWork.Inbox(s));s.AdvanceTo(2);Assert.True(s.Paused);Assert.Null(RegionalWork.Inbox(s).Single().Task);Assert.Contains(w.NpcWork!.Decisions,d=>d.Reason=="offer-local-inspection");Assert.DoesNotContain(w.NpcWork.Decisions,d=>d.Request!=null&&d.Actor!=new EntityId("person:nobunaga"));}
    [Fact] public void NoRepeatedDecisionOrOfferWithoutNewInformation(){var s=New();s.AdvanceTo(2);var count=s.DiagnosticSnapshot().NpcWork!.Decisions.Length;s.SetPaused(false);s.AdvanceTo(10);Assert.Single(s.DiagnosticSnapshot().Tasks);Assert.True(s.DiagnosticSnapshot().NpcWork!.Decisions.Length<=count+1);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot().NpcWork);s.AdvanceTo(15);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot().NpcWork));}
    [Fact] public void KnownReportAndCooldownAreBothRequiredForNextOffer(){var s=New();s.AdvanceTo(2);Accept(s);s.AdvanceTo(9);Assert.Single(s.DiagnosticSnapshot().Tasks);s.AdvanceTo(3600);Assert.Single(s.DiagnosticSnapshot().Tasks);s.AdvanceTo(3601);Assert.Equal(2,s.DiagnosticSnapshot().Tasks.Length);Assert.Equal(3601,s.DiagnosticSnapshot().Requests.Last().CreatedAt);Assert.Equal(2,s.DiagnosticSnapshot().Requests.Select(r=>r.Id).Distinct().Count());}
    [Fact] public void LostReportDoesNotBecomeNpcKnowledgeOrTriggerNewWork(){var s=New();s.AdvanceTo(2);Accept(s);s.AdvanceTo(6);var w=s.DiagnosticSnapshot();var msg=w.Messaging.Messages.Single(m=>m.Kind=="contract-report").Id;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,msg));s.AdvanceTo(4000);Assert.Single(s.DiagnosticSnapshot().Tasks);Assert.Contains(s.DiagnosticSnapshot().NpcWork!.Decisions,d=>d.Reason=="await-own-report");Assert.False(NpcWork.Inputs(s.DiagnosticSnapshot(),new("person:nobunaga"),s.Seconds).LastReportKnown);}
    [Fact] public void HiddenWillingnessCannotChangeThePlanningInput(){var a=NpcWork.Create();var b=ContractJson.Copy(a);b.Characters=b.Characters.Select(c=>c.Id==b.PlayerControl?c with{WillObey=false}:c).ToArray();foreach(var role in RegionalWork.Roles)Assert.Equal(ContractJson.Write(NpcWork.Inputs(a,role.Person,0)),ContractJson.Write(NpcWork.Inputs(b,role.Person,0)));}
    [Fact] public void RoadTravelLeadsToANewLocalDispatcherWithoutTeleport(){var s=New();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:travel","kofu"),s.Revision).Code);s.AdvanceTo(1);Assert.Single(s.DiagnosticSnapshot().Tasks);long at=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt;s.AdvanceTo(at);Assert.Equal(new EntityId("person:shingen"),s.DiagnosticSnapshot().Tasks.Last().Issuer);Assert.Equal(new EntityId("site:kofu"),s.DiagnosticSnapshot().Tasks.Last().Scope);s.AdvanceTo(at+1);Assert.True(s.Paused);Assert.Single(RegionalWork.Inbox(s));}
    [Fact] public void TamperedDecisionInputsAndHashCannotLoadAsValid(){var s=New();s.AdvanceTo(1);var w=s.DiagnosticSnapshot();var d=w.NpcWork!.Decisions[0];w.NpcWork.Decisions[0]=d with{Inputs=d.Inputs with{LocalWitness=!d.Inputs.LocalWitness}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=s.DiagnosticSnapshot();d=w.NpcWork!.Decisions[0];var input=d.Inputs with{LocalWitness=!d.Inputs.LocalWitness};w.NpcWork.Decisions[0]=d with{Inputs=input,InputHash=ContractJson.CanonicalHash(input),Reason=NpcWork.Reason(input)};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Theory][InlineData(1)][InlineData(2)][InlineData(4)][InlineData(6)][InlineData(9)] public void RestorePreservesDecisionsAndDeterministicContinuation(long at){var s=New();s.AdvanceTo(2);if(at>2){Accept(s);s.AdvanceTo(at);}if(at==1){s=New();s.AdvanceTo(1);}var root=Path.Combine(Path.GetTempPath(),"npc-work-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,NpcWork.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.25,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().NpcWork),ContractJson.Write(host.Current.DiagnosticSnapshot().NpcWork));foreach(var q in new[]{s,host.Current}){q.SetPaused(false);if(q.Seconds<2)q.AdvanceTo(2);if(q.DiagnosticSnapshot().Tasks.Single().StartedAt==null)Accept(q);q.AdvanceTo(3601);}Assert.Equal(s.DiagnosticSnapshot().Tasks.Select(t=>(t.RequestId,t.Execution,t.StartedAt,t.FinishedAt)),host.Current.DiagnosticSnapshot().Tasks.Select(t=>(t.RequestId,t.Execution,t.StartedAt,t.FinishedAt)));Assert.Equal(s.DiagnosticSnapshot().NpcWork!.Decisions.Select(d=>new{d.Actor,d.At,d.InputHash,d.Reason,d.Request,d.Result}),host.Current.DiagnosticSnapshot().NpcWork!.Decisions.Select(d=>new{d.Actor,d.At,d.InputHash,d.Reason,d.Request,d.Result}));}
    [Fact] public void DetailedAndCoarseAdvanceKeepTheSameMajorNpcResults(){var a=New();var b=New();foreach(var q in new[]{a,b}){q.AdvanceTo(2);Accept(q);}a.AdvanceTo(3601);foreach(long at in new long[]{3,4,6,7,15,60,500,3601})b.AdvanceTo(at);Assert.Equal(a.DiagnosticSnapshot().Tasks.Select(t=>(t.RequestId,t.Execution,t.StartedAt,t.FinishedAt)),b.DiagnosticSnapshot().Tasks.Select(t=>(t.RequestId,t.Execution,t.StartedAt,t.FinishedAt)));Assert.Equal(a.DiagnosticSnapshot().Requests.Select(q=>(q.Id,q.CreatedAt,q.Intent.Actor)),b.DiagnosticSnapshot().Requests.Select(q=>(q.Id,q.CreatedAt,q.Intent.Actor)));}
    [Fact] public void InsufficientEventBudgetCannotDispatchBehindTheLimit(){var s=New();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());var result=s.AdvanceTo(100,6);Assert.Equal("EventBudget",result.StopReason);Assert.Equal(0,s.Seconds);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void OldRegionalSaveAndFieldDeploymentStaySeparate(){var s=New();Assert.NotEqual(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);var old=RegionalWork.Create();Assert.Null(old.NpcWork);ContractValidation.Validate(old);}
}
